@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + battery : Battery?
  + controller : Controller
}

class Frame {
  + material : string
}

class Wheel {}

class DriveSystem {
  + motor : Motor
}

class Battery {
  + energy : int
}

abstract class Controller {
  + state : string
  + controlBattery(battery: Battery)
  + commandDriveSystem(driveSystem: DriveSystem)
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + estimateInspectionDate()
}

@enduml

